// Page 3 — Career galaxy. Every estimate on this page is a task-comparison
// result or a cited occupational record; nothing is a suitability score.
import {renderCareerStarMap} from '../../star-map.js';
import {renderCareerComparison,renderSkillDNA} from '../../career-explorer.js';
import {renderIntelligence,renderConnections} from '../intelligence.js';
import {galaxySections,galaxySectionLabels} from '../page-map.js';
import {L,card,pageHeader,occupationalCards,renderSourceStatus,renderProvenance,traceLine,signalCards} from './shared.js';
import {escapeHTML as e} from '../../explorer-views.js';

export function renderP0Careers(model){
 const tie=model.p0.rankingStatus==='inconclusive'?`<p class="ex-local-notice">${L('The evidence does not justify putting one route first. Both are priority 1 for exploration; the second card is a display position, not a lower rank.','现有证据不足以让某条路线领先；两条路线均为探索优先级 1。第二张卡片只是显示位置，不代表排名较低。','Bukti belum cukup untuk mendahulukan satu laluan. Kedua-duanya keutamaan penerokaan 1; kad kedua hanya kedudukan paparan.')}</p>`:'';
 return renderIntelligence(model.unified,model.p0.locale||'en')+`<p>${L('Exploration priority compares self-reported task preferences with cited occupational tasks. It is not measured competence, hiring probability or a validated fit score.','探索优先级比较自述任务偏好与有来源的职业任务；它不是已测能力、招聘概率或经过验证的适合度分数。','Keutamaan penerokaan membanding keutamaan tugas kendiri dengan tugas pekerjaan bersumber; ia bukan kebolehan diukur, kebarangkalian pengambilan atau skor kesesuaian sah.')}</p>${tie}<div class="paths-grid">${model.p0.paths.map(p=>card(`${p.priority}. ${p.title}`,`<p>${e(p.why.text)}</p>${traceLine(p.why)}<h4>${L('Tasks and requirements','任务与要求','Tugas dan keperluan')}</h4><p lang="en">${e(p.tasks.join(' · '))}</p><p lang="en">${e(p.requirements.join(' · '))}</p><p>${e(p.unmeasured)}</p><h4>${L('Next evidence','下一项证据','Bukti seterusnya')}</h4><p>${e(p.action.task)}</p><p>${e(p.action.check)}</p><small>${p.officialMapping?L('Reviewed occupational source; task-to-answer link is a product inference','已审阅职业来源；任务与答案关联属于产品推断','Sumber pekerjaan disemak; kaitan tugas-jawapan ialah inferens produk'):L('Team editorial catalog; official route mapping unavailable','团队职业目录；暂无已审阅的官方路线映射','Katalog editorial pasukan; pemetaan rasmi laluan tiada')}${(p.source.relatedSourceIds||[p.source.id]).map(id=>{const s=model.report.evidence.sources[id];return s?.url?` · <a href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(id)} ↗</a>`:'';}).join('')}${p.source.mappingCaveat?` · ${e(p.source.mappingCaveat)}`:''}</small>`)).join('')}</div>`;
}

function sectionNav(active){
 return `<nav class="galaxy-tabs" aria-label="${L('Career galaxy sections','职业星系分区','Bahagian galaksi kerjaya')}">${galaxySections.map(id=>`<button type="button" data-combined-action="section:${id}" class="${id===active?'active':''}" ${id===active?'aria-current="true"':''}>${e(L(...galaxySectionLabels[id]))}</button>`).join('')}</nav>`;
}
export function renderGalaxyPage(model,options={},section='map'){
 const path=options.path||'A';
 let body='';
 if(section==='paths')body=`<p>${L('Explore these direction-specific contexts side by side. They are not ranked or scored for personal suitability. Source skill requirements are not measured personal skill gaps.','可并列比较以下方向相关背景，不按个人适合度排序或计分。来源中的技能要求不等于已测量的个人能力缺口。','Banding konteks khusus arah ini. Ia tidak diberi kedudukan atau skor kesesuaian. Keperluan kemahiran sumber bukan jurang kemahiran peribadi yang diukur.')}</p><div class="paths-grid">${occupationalCards(model)}</div>${renderP0Careers(model)}`;
 if(section==='map')body=`<p>${L('Each route is a reviewed occupational context, not a prediction that you should choose it. Select a route to read its tasks, requirements and the experiment that would test it.','每条路线都是已审阅的职业背景，而不是“你应该选择它”的预测。选择路线可查看任务、要求，以及用于验证它的实验。','Setiap laluan ialah konteks pekerjaan disemak, bukan ramalan bahawa anda patut memilihnya. Pilih laluan untuk membaca tugas, keperluan dan eksperimen untuk mengujinya.')}</p>${renderCareerStarMap(model.report,path)}`;
 if(section==='compare')body=model.contexts.candidates.length>1?`<p>${L('Two routes, same evidence. The comparison shows where the cited requirements differ; it does not declare a winner.','两条路线，同一份证据。对比展示来源要求的差异，不宣布哪条更好。','Dua laluan, bukti sama. Perbandingan menunjukkan perbezaan keperluan bersumber; ia tidak mengisytiharkan pemenang.')}</p>${renderCareerComparison(model.report,path,path==='A'?'B':'A')}`:`<p class="ex-local-notice">${L('Only one reviewed route exists for this direction, so there is nothing to compare. Open Career paths to see its tasks.','该方向仅有一条已审阅路线，暂无可对比对象。可在“职业路径”查看其任务。','Hanya satu laluan disemak bagi arah ini, jadi tiada perbandingan. Buka Laluan kerjaya untuk melihat tugasnya.')}</p>`;
 if(section==='skills')body=`<p>${L('Skills to investigate, not verified strengths or deficits. Use a work sample to check each requirement.','以下是需了解的技能，不是已验证优势或不足；请通过工作样本逐项核验。','Kemahiran untuk diterokai, bukan kekuatan atau kekurangan disahkan. Semak setiap keperluan melalui sampel kerja.')}</p><div class="local-dimensions">${occupationalCards(model)}</div>${renderSkillDNA(model.report,path,options.skill||'')}${signalCards(model,['experience','workstyle'])}${renderConnections(model.unified,model.p0.locale||'en')}`;
 return `${pageHeader('galaxy')}${sectionNav(section)}<section class="galaxy-section" data-galaxy-section="${e(section)}">${body}</section>${renderSourceStatus(model)}${renderProvenance(model)}`;
}
